#pragma once
#include "Applications.h"
#include "AssetTransfers.h"
namespace notesos {
// Device AI broker. Provider/Harness protocols live upstream; the broker owns
// request lifetime, origin routing and typed system-result application.
class AgentService {
 struct Task{uint32_t id=0,origin=0,remote=0;char target[16]{},state[24]{},error[80]{},key[65]{},effectPath[48]{},effectMethod[32]{},operationKey[65]{};uint32_t follows=0;JsonDocument result;bool detached=false,applyNext=false;uint32_t effect=0;};
 struct EffectReceipt{char key[65]{},error[80]{},hash[65]{};bool used=false;};EffectReceipt receipts_[8];unsigned receiptAt_=0;
 Core&core_;AssetTransfers&assets_;Task tasks_[4];uint32_t next_=1,owner_=0;JsonDocument config_;
 Task*find(uint32_t id){for(auto&t:tasks_)if(t.id==id&&id)return &t;return nullptr;}
 static void effectHash(JsonVariantConst value,char out[65]){Sha256 hash;struct Writer{Sha256&hash;size_t write(uint8_t b){hash.update(&b,1);return 1;}size_t write(const uint8_t*p,size_t n){hash.update(p,n);return n;}}writer{hash};serializeJson(value,writer);hash.finish(out);}
 EffectReceipt*receipt(const char*key){if(!*key)return nullptr;for(auto&r:receipts_)if(r.used&&!strcmp(r.key,key))return &r;return nullptr;}
 void changed(Task&t,const char*event){if(*t.operationKey&&t.result["effects"].size()&&(!strcmp(event,"completed")||!strcmp(event,"failed"))){auto*r=receipt(t.operationKey);if(!r)r=&receipts_[receiptAt_++%8];r->used=true;copy(r->key,sizeof r->key,t.operationKey);copy(r->error,sizeof r->error,t.error);effectHash(t.result["effects"],r->hash);}
JsonDocument d;d["id"]=t.id;d["request_id"]=t.key;d["state"]=t.state;d["ok"]=!strcmp(event,"completed");d["error"]=t.error;d["target"]=t.target;if(t.origin&&!t.detached)core_.emit("/services/ai",event,d.as<JsonObjectConst>(),t.origin);else core_.emit("/services/ai",event,d.as<JsonObjectConst>(),owner_);}
 void fail(Task&t,const char*e){copy(t.error,sizeof t.error,e);strcpy(t.state,"failed");changed(t,"failed");}
 const char*validateResult(Task&t,JsonObjectConst result,bool skipAssets=false){if(auto e=argumentFields(result,"format,operation_id,application,effects"))return e;if(result["format"]!="wishos-result/1"||!result["application"].isNull()&&!result["application"].is<JsonObjectConst>())return "ai_result_format";
 if(result.containsKey("operation_id")&&(!result["operation_id"].is<const char*>()||strlen(result["operation_id"])>64))return "ai_operation_identity";auto effects=result["effects"].as<JsonArrayConst>();if(!result["effects"].isNull()&&effects.isNull()||effects.size()>1)return "ai_effect_limit";if(!strcmp(t.target,"application")&&effects.size())return "ai_target_scope";
 if(!strcmp(t.target,"system")&&!result["application"].isNull())return "ai_target_scope";
 for(auto effect:effects){const char*kind=effect["kind"]|"";if(!Core::containsMethod("application,presentation,resource_call",kind))return "ai_effect_kind";const char*fields=!strcmp(kind,"application")?"kind,path,transfer_id,persist,activate":!strcmp(kind,"presentation")?"kind,path,transfer_id,driver":"kind,path,method,args";if(auto e=argumentFields(effect.as<JsonObjectConst>(),fields))return e;if(effect.containsKey("activate")&&!effect["activate"].is<bool>()||effect.containsKey("driver")&&!effect["driver"].is<const char*>())return "ai_effect_type";if(!strcmp(kind,"resource_call")){const char*path=effect["path"]|"",*method=effect["method"]|"";auto device=core_.find(path);if(!device||!core_.supports(*device,method)||!effect["args"].is<JsonObjectConst>())return "ai_resource_call";if(Core::containsMethod("/sys/runtime,/sys/apps,/services/ai,/sys/transfers",path))return "ai_requires_typed_effect";continue;}if(skipAssets)continue;char file[256];if(auto e=assets_.verified(effect["transfer_id"]|0u,effect["path"]|"",file,sizeof file))return e;
  if(!strcmp(kind,"presentation")&&!core_.find("/sys/ui"))return "display_unavailable";
 }return nullptr;}
public:
 static constexpr const char*Methods="read,configure,submit,cancel,release";using Save=bool(*)(const char*,size_t);
 AgentService(Core&c,AssetTransfers&a):core_(c),assets_(a){owner_=core_.acquireOwner();config_["route"]="wishos.ai";config_["timeout_ms"]=900000;core_.onOwnerRelease(this,[](void*p,uint32_t owner){auto&s=*static_cast<AgentService*>(p);for(auto&t:s.tasks_)if(t.origin==owner)t.detached=true;});}
 ~AgentService(){core_.removeOwnerHook(this);core_.releaseOwner(owner_);}
 bool restore(const char*s){JsonDocument d,o;if(deserializeJson(d,s))return false;JsonDocument a;a["settings"]=d;return !invoke("configure",a.as<JsonObjectConst>(),o.to<JsonObject>());}
 const char*invoke(const char*m,JsonObjectConst a,JsonObject o,Save save=nullptr){if(auto e=argumentFields(a,!strcmp(m,"configure")?"settings,persist":!strcmp(m,"submit")?"target,input,request_id,timeout_ms":"id"))return e;
 if(!strcmp(m,"configure")){auto settings=a["settings"].as<JsonObjectConst>();if(settings.isNull())return "ai_configuration";JsonDocument next;next.set(config_);for(auto f:settings){if(!Core::containsMethod("route,timeout_ms",f.key().c_str()))return "unknown_ai_setting";next[f.key()]=f.value();}if(!next["route"].is<const char*>()||!strlen(next["route"])||strlen(next["route"])>64||!next["timeout_ms"].is<uint32_t>()||next["timeout_ms"].as<uint32_t>()<100||next["timeout_ms"].as<uint32_t>()>86400000)return "ai_configuration";char text[256];size_t n=serializeJson(next,text,sizeof text);if((a["persist"]|false)&&(!save||!save(text,n)))return "persistence_failed";swap(config_,next);o["configured"]=config_;return nullptr;}
 if(!strcmp(m,"submit")){for(auto f:a)if(!Core::containsMethod("target,input,request_id,timeout_ms",f.key().c_str()))return "unknown_ai_argument";for(auto key:{"target","request_id"})if(a.containsKey(key)&&!a[key].is<const char*>())return "ai_request_type";const char*target=a["target"]|"application";if(!Core::containsMethod("application,system,both",target)||!a["input"].is<JsonObjectConst>())return "ai_request";const char*key=a["request_id"]|"";if(strlen(key)>64)return "ai_request_id";Task*t=nullptr;for(auto&x:tasks_)if(!x.id){t=&x;break;}if(!t)for(auto&x:tasks_)if(x.detached&&(!strcmp(x.state,"completed")||!strcmp(x.state,"failed"))){x=Task();t=&x;break;}if(!t)return "ai_queue_full";
 JsonDocument args,reply;args["route"]=config_["route"];args["timeout_ms"]=a["timeout_ms"]|config_["timeout_ms"].as<uint32_t>();if(*key)args["request_id"]=key;args["payload"]["format"]="wishos-ai/1";args["payload"]["target"]=target;args["payload"]["input"]=a["input"];if(args.overflowed())return "memory_low";
 if(auto e=core_.invoke("/services/remote","submit",args.as<JsonObjectConst>(),reply.to<JsonObject>(),owner_))return e;
 for(auto&old:tasks_)if(old.id&&old.remote==reply["id"].as<uint32_t>()){if(old.origin!=core_.callerOwner())return "ai_request_owned_by_other";o["id"]=old.id;o["state"]=old.state;return nullptr;}
 t->id=next_++;t->origin=core_.callerOwner();t->remote=reply["id"];copy(t->key,sizeof t->key,reply["request_id"]|"");strcpy(t->target,target);strcpy(t->state,"queued");o["id"]=t->id;o["request_id"]=t->key;o["state"]=t->state;return nullptr;}
 if(!strcmp(m,"read")&&!a.containsKey("id")){o["configured"]=config_;auto list=o["tasks"].to<JsonArray>();for(auto&t:tasks_)if(t.id&&(!core_.callerOwner()||t.origin==core_.callerOwner())){auto x=list.add<JsonObject>();x["id"]=t.id;x["state"]=t.state;x["target"]=t.target;x["detached"]=t.detached;}return nullptr;}
 auto*t=find(a["id"]|0u);if(!t)return "ai_request_not_found";if(core_.callerOwner()&&t->origin!=core_.callerOwner())return "ai_request_owned_by_other";
 if(!strcmp(m,"cancel")){if(t->applyNext||t->effect)return "ai_effect_already_admitted";JsonDocument r,out;r["id"]=t->remote;r["ok"]=false;r["result"]["error"]="cancelled";core_.invoke("/services/remote","complete",r.as<JsonObjectConst>(),out.to<JsonObject>(),owner_);JsonDocument released,release;release["id"]=t->remote;core_.invoke("/services/remote","release",release.as<JsonObjectConst>(),released.to<JsonObject>(),owner_);fail(*t,"cancelled");}
 else if(!strcmp(m,"release")){if(strcmp(t->state,"completed")&&strcmp(t->state,"failed"))return "ai_request_pending";*t=Task();return nullptr;}
 else if(strcmp(m,"read"))return "unsupported_method";
 o["id"]=t->id;o["state"]=t->state;o["target"]=t->target;o["error"]=t->error;o["result"]=t->result;return nullptr;
 }
 void poll(){for(auto&t:tasks_)if(t.id){
  if(t.follows){auto leader=find(t.follows);auto prior=receipt(t.operationKey);if(prior){t.follows=0;if(*prior->error)fail(t,prior->error);else{strcpy(t.state,"completed");changed(t,"completed");}}else if(!leader)fail(t,"ai_effect_receipt_missing");continue;}

  if(t.effect){JsonDocument done;auto e=core_.completions().read(t.effect,owner_,done.to<JsonObject>());if(e){t.effect=0;fail(t,e);continue;}if(!(done["ready"]|false))continue;core_.completions().release(t.effect,owner_);t.effect=0;JsonDocument description;core_.describe(t.effectPath,description.to<JsonObject>());bool success=false;for(auto event:description["async"][t.effectMethod]["success_events"].as<JsonArrayConst>())if(event==done["event"])success=true;if(!success||done["data"]["ok"]==false){fail(t,done["data"]["error"]|"ai_effect_failed");continue;}strcpy(t.state,"completed");changed(t,"completed");continue;}
  if(t.applyNext){t.applyNext=false;auto effect=t.result["effects"][0];char file[256];if(effect["kind"]!="resource_call")if(auto e=assets_.verified(effect["transfer_id"]|0u,effect["path"]|"",file,sizeof file)){fail(t,e);continue;}JsonDocument args,out;const char*error=nullptr;
   if(effect["kind"]=="application"){args["manifest"]=file;args["persist"]=effect["persist"]|false;error=core_.invoke("/sys/apps","install",args.as<JsonObjectConst>(),out.to<JsonObject>());if(!error&&effect["activate"]!=false){JsonDocument launch;launch["id"]=out["application_id"];out.clear();copy(t.effectPath,sizeof t.effectPath,"/sys/apps");copy(t.effectMethod,sizeof t.effectMethod,"launch");error=core_.request("/sys/apps","launch",launch.as<JsonObjectConst>(),out.to<JsonObject>(),owner_);if(!error)t.effect=out["completion_id"];}}
   else if(effect["kind"]=="resource_call"){JsonDocument schema;const char*path=effect["path"],*method=effect["method"];core_.describe(path,schema.to<JsonObject>());if(schema["async"].as<JsonObjectConst>().containsKey(method)){copy(t.effectPath,sizeof t.effectPath,path);copy(t.effectMethod,sizeof t.effectMethod,method);error=core_.request(path,method,effect["args"],out.to<JsonObject>(),owner_);if(!error)t.effect=out["completion_id"];}else error=core_.invoke(path,method,effect["args"],out.to<JsonObject>());}
   else{args["path"]=file;args["history"]="replace";if(effect["driver"].is<const char*>())args["driver"]=effect["driver"];copy(t.effectPath,sizeof t.effectPath,"/sys/ui");copy(t.effectMethod,sizeof t.effectMethod,"open");error=core_.request("/sys/ui","open",args.as<JsonObjectConst>(),out.to<JsonObject>(),owner_);if(!error)t.effect=out["completion_id"];}
   if(!error&&effect["kind"]!="resource_call"){JsonDocument release,ignored;release["id"]=effect["transfer_id"];assets_.invoke("release",release.as<JsonObjectConst>(),ignored.to<JsonObject>());}if(error)fail(t,error);else if(!t.effect){strcpy(t.state,"completed");changed(t,"completed");}else strcpy(t.state,"applying");continue;}
  if(strcmp(t.state,"queued"))continue;JsonDocument args,reply;args["id"]=t.remote;auto e=core_.invoke("/services/remote","read",args.as<JsonObjectConst>(),reply.to<JsonObject>(),owner_);if(e){fail(t,e);continue;}if(reply["state"]=="queued")continue;
  if(reply["state"]=="failed"){fail(t,reply["result"]["error"]|"ai_remote_failed");}else{auto result=reply["result"].as<JsonObjectConst>();const char*key=result["operation_id"]|"";copy(t.operationKey,sizeof t.operationKey,key);auto prior=result["effects"].size()?receipt(key):nullptr;Task*leader=nullptr;if(*key&&result["effects"].size())for(auto&other:tasks_)if(&other!=&t&&other.id&&!other.follows&&!strcmp(other.operationKey,key)){leader=&other;break;}
  const char*validation=validateResult(t,result,prior||leader);if(!validation&&(prior||leader)){char expected[65],actual[65];effectHash(result["effects"],actual);if(prior)copy(expected,sizeof expected,prior->hash);else effectHash(leader->result["effects"],expected);if(strcmp(expected,actual))validation="ai_operation_conflict";}if(validation)fail(t,validation);else if(prior||leader){t.result.set(result);if(prior){if(*prior->error)fail(t,prior->error);else{strcpy(t.state,"completed");changed(t,"completed");}}else{t.follows=leader->id;strcpy(t.state,"following");}}else{t.result.set(result);if(t.result.overflowed())fail(t,"memory_low");else if(t.result["effects"].size()){strcpy(t.state,"result_ready");t.applyNext=true;changed(t,"result_ready");}else{strcpy(t.state,"completed");changed(t,"completed");}}}
  reply.clear();core_.invoke("/services/remote","release",args.as<JsonObjectConst>(),reply.to<JsonObject>(),owner_);
 }}
 void describe(JsonObject o)const{o["scope"]="system_ai_broker";o["request_lifetime"]="independent_of_origin_application";o["targets"]="application,system,both";o["result_format"]="wishos-result/1";o["pending_capacity"]=4;o["inline_result_limit_bytes"]=1536;o["effect_limit_per_result"]=1;o["lifetime"]="current_boot";o["duplicate_effect_receipts"]=8;o["system_effects"]="application,presentation,resource_call";o["large_resources"]="/sys/transfers";o["provider_protocols"]="upstream_adapter";asyncContract(o,"submit","/services/ai")["id"]="id";}
};
}
